#!/usr/bin/env node
/**
 * design-tokens.json → src/styles/tokens.css
 *
 * One source, one generated file. `global.css` imports the output and declares no
 * palette of its own, so a colour cannot be changed in one place and stay stale in the
 * other — which is the failure this script exists to prevent, not a style preference.
 *
 * The token file is W3C Design Tokens Community Group shaped: `$type` / `$value`, with
 * `{group.token}` references for aliases. An alias compiles to `var(--other)` rather
 * than to the resolved literal, so the alias stays live: repoint the target and every
 * borrower moves with it.
 *
 * A token's custom-property name comes from `$extensions.site.cssVar` when it is
 * pinned, and otherwise from its path with the leading group dropped for colours
 * (`color.brand.primary` → `--brand-primary`).
 *
 * Usage: node scripts/build-tokens.mjs [--check]
 *   --check  exit 1 if tokens.css is missing or out of date, and write nothing.
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(here, '..');
const SOURCE = path.join(root, 'design-tokens.json');
const TARGET = path.join(root, 'src', 'styles', 'tokens.css');

/** Every key a group can carry that is metadata rather than a child token. */
const META = new Set(['$type', '$value', '$description', '$extensions', '$deprecated']);

/**
 * Walk the tree, collecting leaves (anything with a `$value`) in declaration order.
 * `$type` is inherited from the nearest ancestor that declares one, as the spec says.
 */
function collect(node, trail = [], inheritedType = null) {
  const type = node.$type ?? inheritedType;
  if (Object.hasOwn(node, '$value')) {
    return [{ path: trail, type, value: node.$value, extensions: node.$extensions }];
  }
  const out = [];
  for (const [key, child] of Object.entries(node)) {
    if (META.has(key) || child === null || typeof child !== 'object') continue;
    out.push(...collect(child, [...trail, key], type));
  }
  return out;
}

function cssVarName(token) {
  const pinned = token.extensions?.site?.cssVar;
  if (pinned) return pinned;
  const trail = token.path[0] === 'color' ? token.path.slice(1) : token.path;
  return `--${trail.join('-')}`;
}

const ALIAS = /^\{([^}]+)\}$/;

/** `4px` / `0` / `2px` — a shadow length, straight through. */
function len(value) {
  return value === 0 || value === '0' ? '0' : String(value);
}

function shadowLayer(layer) {
  return [
    len(layer.offsetX ?? 0),
    len(layer.offsetY ?? 0),
    len(layer.blur ?? 0),
    ...(layer.spread && len(layer.spread) !== '0' ? [len(layer.spread)] : []),
    layer.color,
  ].join(' ');
}

/** A family name with a space in it has to be quoted in a CSS font stack. */
function fontFamily(value) {
  const list = Array.isArray(value) ? value : [value];
  return list.map((name) => (/\s/.test(name) ? `'${name}'` : name)).join(', ');
}

function render(token, byPath) {
  const { value, type } = token;

  if (typeof value === 'string') {
    const alias = ALIAS.exec(value.trim());
    if (alias) {
      const target = byPath.get(alias[1]);
      if (!target) throw new Error(`${token.path.join('.')} references {${alias[1]}}, which does not exist`);
      return `var(${cssVarName(target)})`;
    }
    return value;
  }

  if (type === 'fontFamily') return fontFamily(value);
  if (type === 'shadow') return (Array.isArray(value) ? value : [value]).map(shadowLayer).join(', ');
  if (type === 'cubicBezier') return `cubic-bezier(${value.join(', ')})`;
  return String(value);
}

function build() {
  const source = JSON.parse(readFileSync(SOURCE, 'utf8'));
  const tokens = collect(source);
  const byPath = new Map(tokens.map((t) => [t.path.join('.'), t]));

  const seen = new Map();
  const lines = [];
  let group = null;

  for (const token of tokens) {
    const name = cssVarName(token);
    if (seen.has(name)) {
      throw new Error(`${name} is declared twice: ${seen.get(name)} and ${token.path.join('.')}`);
    }
    seen.set(name, token.path.join('.'));

    // A blank line between top-level groups is the only formatting this file has.
    const head = token.path.slice(0, token.path.length > 2 ? 2 : 1).join('.');
    if (group !== null && head !== group) lines.push('');
    group = head;

    lines.push(`  ${name}: ${render(token, byPath)};`);
  }

  return [
    '/* GENERATED by scripts/build-tokens.mjs from design-tokens.json — do not edit.',
    '   Change a value in design-tokens.json and run `pnpm tokens`. */',
    '',
    ':root {',
    ...lines,
    '}',
    '',
  ].join('\n');
}

const css = build();

if (process.argv.includes('--check')) {
  const current = existsSync(TARGET) ? readFileSync(TARGET, 'utf8') : null;
  if (current !== css) {
    process.stderr.write('tokens.css is out of date with design-tokens.json — run `pnpm tokens`.\n');
    process.exit(1);
  }
  process.stdout.write('tokens.css matches design-tokens.json.\n');
} else {
  writeFileSync(TARGET, css);
  process.stdout.write(`wrote ${path.relative(root, TARGET)} — ${css.split('\n').length - 6} tokens.\n`);
}
